795	  // 成员现状（被改期/取消）与首次请求不同不算损坏。
796	  const importUids = new Set<string>();
797	  const importLinkedBookings = new Set<string>();
798	  const importLinkedSeries = new Set<string>();
799	  const claimBooking = (uid: string, bId: string, at: string): void => {
800	    if (!bookingById.has(bId)) bad(`${at}(UID “${uid}”) 关联了未知预约: ${bId}`);
801	    if (importLinkedBookings.has(bId)) {
802	      bad(`${at}(UID “${uid}”) 预约 ${bId} 已被另一条导入记录关联（一项预约只能对应一个 UID）`);
803	    }
804	    importLinkedBookings.add(bId);
805	  };
806	  rawImports.forEach((item, idx) => {
807	    const at = `imports[${idx}]`;
808	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
809	    const im = item as Record<string, unknown>;
810	    if (typeof im.uid !== 'string' || im.uid === '') bad(`${at}.uid 必须是非空字符串`);
811	    if (importUids.has(im.uid)) bad(`导入记录 UID 重复: ${im.uid}`);
812	    importUids.add(im.uid);
813	    const uid = im.uid;
814	
815	    const hasBooking = im.bookingId !== undefined;
816	    const hasSeries = im.seriesId !== undefined;
817	    if (hasBooking === hasSeries) {
818	      bad(`${at}(UID “${uid}”) 必须恰好提供 bookingId（独立事件）或 seriesId（重复事件）之一`);
819	    }
820	    if (typeof im.start !== 'string' || typeof im.end !== 'string') {
821	      bad(`${at}(UID “${uid}”) 快照起止时间必须是字符串`);
822	    }
823	    const s = parseDateTime(im.start as string, `${at}(UID “${uid}”).start`);
824	    const e = parseDateTime(im.end as string, `${at}(UID “${uid}”).end`);
825	    if (e <= s) bad(`${at}(UID “${uid}”) 快照结束必须晚于开始`);
826	    if (!Array.isArray(im.resourceIds) || im.resourceIds.length === 0) {
827	      bad(`${at}(UID “${uid}”).resourceIds 必须是非空数组`);
828	    }
829	    const rids = im.resourceIds as unknown[];
830	    const rseen = new Set<string>();
831	    rids.forEach((rid) => {
832	      if (typeof rid !== 'string' || !resourceIds.has(rid)) {
833	        bad(`${at}(UID “${uid}”) 快照引用了未知资源: ${String(rid)}`);
834	      }
835	      if (rseen.has(rid)) bad(`${at}(UID “${uid}”) 快照资源重复: ${rid}`);
836	      rseen.add(rid);
837	    });
838	
839	    const rec: ImportRec = {
840	      uid,
841	      start: im.start as string,
842	      end: im.end as string,
843	      resourceIds: [...rseen].sort(),
844	    };
845	
846	    if (hasBooking) {
847	      // 独立事件身份：不得携带重复字段
848	      if (typeof im.bookingId !== 'string' || !/^B\d{4,}$/.test(im.bookingId)) {
849	        bad(`${at}(UID “${uid}”).bookingId 非法: ${String(im.bookingId)}`);
850	      }
851	      for (const k of ['count', 'exdates', 'occurrences']) {
852	        if (im[k] !== undefined) bad(`${at}(UID “${uid}”) 独立事件身份不应携带 ${k}`);
853	      }
854	      claimBooking(uid, im.bookingId as string, at);
855	      rec.bookingId = im.bookingId as string;
856	      store.imports.push(rec);
857	      return;
858	    }
859	
860	    // 重复事件身份
861	    if (typeof im.seriesId !== 'string' || !/^S\d{4,}$/.test(im.seriesId)) {
862	      bad(`${at}(UID “${uid}”).seriesId 非法: ${String(im.seriesId)}`);
863	    }
864	    if (!seriesIds.has(im.seriesId)) {
865	      bad(`${at}(UID “${uid}”) 关联了未知系列: ${im.seriesId}`);
866	    }
867	    if (importLinkedSeries.has(im.seriesId)) {
868	      bad(`${at}(UID “${uid}”) 系列 ${im.seriesId} 已被另一条导入记录关联（一个系列只能对应一个 UID）`);
869	    }
870	    importLinkedSeries.add(im.seriesId);
871	    rec.seriesId = im.seriesId;
872	
873	    if (!isInt(im.count) || im.count < 1 || im.count > MAX_OCCURRENCES) {
874	      bad(`${at}(UID “${uid}”).count 必须是 1..${MAX_OCCURRENCES} 的整数`);
875	    }
876	    rec.count = im.count;
877	    if (!Array.isArray(im.exdates)) bad(`${at}(UID “${uid}”).exdates 必须是数组`);
878	    const exSet = new Set<string>();
879	    (im.exdates as unknown[]).forEach((xv, j) => {
880	      if (typeof xv !== 'string') bad(`${at}(UID “${uid}”).exdates[${j}] 必须是时间字符串`);
881	      parseDateTime(xv, `${at}(UID “${uid}”).exdates[${j}]`);
882	      if (exSet.has(xv)) bad(`${at}(UID “${uid}”) 排除时间重复: ${xv}`);
883	      exSet.add(xv);
884	    });
885	    rec.exdates = [...exSet].sort();
886	
887	    if (!Array.isArray(im.occurrences) || im.occurrences.length === 0) {
888	      bad(`${at}(UID “${uid}”).occurrences 必须是非空数组（全部发生被排除的首次请求非法）`);
889	    }
890	    const occTimes = new Set<string>();
891	    const occs: Array<{start: string; bookingId: string}> = [];
892	    (im.occurrences as unknown[]).forEach((ov, j) => {
893	      const oat = `${at}(UID “${uid}”).occurrences[${j}]`;
894	      if (typeof ov !== 'object' || ov === null || Array.isArray(ov)) bad(`${oat} 必须是对象`);
895	      const o = ov as Record<string, unknown>;
896	      for (const k of Object.keys(o)) {
897	        if (k !== 'start' && k !== 'bookingId') bad(`${oat} 存在未知字段 “${k}”`);
898	      }
899	      if (typeof o.start !== 'string') bad(`${oat}.start 必须是时间字符串`);
900	      parseDateTime(o.start, `${oat}.start`);
901	      if (occTimes.has(o.start)) bad(`${at}(UID “${uid}”) 原发生时间重复: ${o.start}`);
902	      occTimes.add(o.start);
903	      if (typeof o.bookingId !== 'string' || !/^B\d{4,}$/.test(o.bookingId)) {
904	        bad(`${oat}.bookingId 非法: ${String(o.bookingId)}`);
905	      }
906	      claimBooking(uid, o.bookingId, at);
907	      occs.push({start: o.start, bookingId: o.bookingId});
908	    });
909	
910	    // 映射自洽性：按首项与 COUNT 展开全部原发生（须在四位年份内），
911	    // 未排除发生必须恰好等于 occurrences（时间集合一致、顺序按发生先后）
912	    const expectedAll: string[] = [];
913	    for (let i = 0; i < rec.count; i++) {
914	      const raw = formatDateTime(s + i * 7 * 1440);
915	      if (raw === null) bad(`${at}(UID “${uid}”) 重复展开超出四位年份范围（0001-9999）`);
916	      expectedAll.push(raw);
917	    }
918	    const expectedKept = expectedAll.filter((t) => !exSet.has(t));
919	    const excludedNotInSeries = [...exSet].filter((t) => !expectedAll.includes(t));
920	    if (excludedNotInSeries.length > 0) {
921	      bad(`${at}(UID “${uid}”) 排除时间不匹配任何原发生: ${excludedNotInSeries.join('、')}`);
922	    }
923	    if (occs.length !== expectedKept.length || occs.some((o, j) => o.start !== expectedKept[j])) {
924	      bad(
925	        `${at}(UID “${uid}”) 发生映射缺漏或重复：COUNT=${rec.count}、排除 ${exSet.size} 项` +
926	          `时应有 ${expectedKept.length} 个未排除发生且按发生顺序排列`,
927	      );
928	    }
929	    // 成员必须恰好为所关联系列的全部成员（1:1：系列成员不重不漏）
930	    const seriesMembers = new Set(
931	      store.bookings.filter((b) => b.seriesId === rec.seriesId).map((b) => b.id),
932	    );
933	    for (const o of occs) {
934	      if (!seriesMembers.has(o.bookingId)) {
935	        bad(`${at}(UID “${uid}”) 成员 ${o.bookingId} 不属于系列 ${rec.seriesId}`);
936	      }
937	    }
938	    if (occs.length !== seriesMembers.size) {
939	      bad(`${at}(UID “${uid}”) 系列 ${rec.seriesId} 存在未登记在 occurrences 中的成员（系列与发生映射必须一一对应）`);
940	    }
941	    rec.occurrences = occs;
942	    store.imports.push(rec);
943	  });
944	
945	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
946	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
947	  store.series.sort((a, b) => a.id.localeCompare(b.id));
948	  store.waitlist.sort((a, b) => a.seq - b.seq || a.id.localeCompare(b.id));
949	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
950	  store.batchOps.sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
951	  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
952	  return store;
953	}
