1005	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1006	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1007	  const problems: string[] = [];
1008	  const seen = new Set<string>();
1009	  const dupes: string[] = [];
1010	  for (const id of rawIds) {
1011	    if (seen.has(id)) {
1012	      if (!dupes.includes(id)) dupes.push(id);
1013	    }
1014	    seen.add(id);
1015	  }
1016	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1017	
1018	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1019	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1020	
1021	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1022	  return [...seen].sort();
1023	}
