1055	// 某资源的有效停用记录（按开始时间、标识排序）
1056	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1057	  return store.closures
1058	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1059	    .sort(
1060	      (a, b) =>
1061	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1062	        a.id.localeCompare(b.id),
1063	    );
1064	}
1065	
1066	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
1067	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
1068	  const cuts = activeClosuresOf(store, r.id).map(
1069	    (c) =>
1070	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
1071	  );
1072	  return subtractSegments(openSegmentsOf(r), cuts);
1073	}
