1154	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1155	  if (conflicts.length === 0) return;
1156	  const lines = conflicts.map(
1157	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1158	  );
1159	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1160	}
