1229	function splitGlobalArgs(argv: string[]): GlobalArgs {
1230	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1231	  for (let i = 0; i < argv.length; i++) {
1232	    const a = argv[i];
1233	    if (a === '-h' || a === '--help') {
1234	      result.help = true;
1235	    } else if (a === '--data') {
1236	      const v = argv[++i];
1237	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1238	      result.dataFile = v;
1239	    } else if (a.startsWith('--data=')) {
1240	      result.dataFile = a.slice('--data='.length);
1241	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1242	    } else {
1243	      result.rest.push(a);
1244	    }
1245	  }
1246	  return result;
1247	}
