1475	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1476	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1477	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1478	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1479	  }
1480	  const o = raw as Record<string, unknown>;
1481	  for (const k of Object.keys(o)) {
1482	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1483	  }
1484	  if (!Array.isArray(o.items)) {
1485	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1486	  }
1487	  const items = o.items as unknown[];
1488	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1489	
1490	  const problems: string[] = [];
1491	  const records: Array<Record<string, unknown> | null> = [];
1492	  items.forEach((it, idx) => {
1493	    const at = `第 ${idx + 1} 项`;
1494	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1495	      problems.push(`${at} 必须是对象`);
1496	      records.push(null);
1497	      return;
1498	    }
1499	    const rec = it as Record<string, unknown>;
1500	    for (const k of Object.keys(rec)) {
1501	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1502	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1503	      }
1504	    }
1505	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1506	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1507	    }
1508	    if (typeof rec.start !== 'string' || rec.start === '') {
1509	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1510	    }
1511	    if (typeof rec.end !== 'string' || rec.end === '') {
1512	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1513	    }
1514	    if (!Array.isArray(rec.resourceIds)) {
1515	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1516	    } else {
1517	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1518	      rec.resourceIds.forEach((rid, j) => {
1519	        if (typeof rid !== 'string' || rid === '') {
1520	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1521	        }
1522	      });
1523	    }
1524	    records.push(rec);
1525	  });
1526	  if (problems.length > 0) {
1527	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1528	  }
1529	  return records as Array<Record<string, unknown>>;
1530	}
