1999	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
2000	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
2001	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
2002	  const members: PlannedMember[] = [];
2003	  for (let i = 0; i < count; i++) {
2004	    const s = startMin + i * 7 * 1440;
2005	    const e = endMin + i * 7 * 1440;
2006	    const startRaw = formatDateTime(s);
2007	    const endRaw = formatDateTime(e);
2008	    if (startRaw === null || endRaw === null) {
2009	      const nth = i + 1;
2010	      throw new BizError(
2011	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
2012	          '请缩短次数或改选更早的首项时间',
2013	      );
2014	    }
2015	    members.push({startRaw, endRaw, startMin: s, endMin: e});
2016	  }
2017	  return members;
2018	}
