2718	// 标准折行展开：以空格或制表符开头的行是上一行的延续（去掉首个空白字符拼接）。
2719	// 同时支持 CRLF 与 LF 行尾；空行忽略（文件末尾换行自然被吞掉）。
2720	function unfoldIcalLines(text: string, bad: (reason: string) => never): string[] {
2721	  const lines: string[] = [];
2722	  for (const raw of text.split(/\r\n|\n/)) {
2723	    if (raw === '') continue;
2724	    if (raw.startsWith(' ') || raw.startsWith('\t')) {
2725	      if (lines.length === 0) bad('文件以折行续行开头，缺少被延续的内容行');
2726	      lines[lines.length - 1] += raw.slice(1);
2727	    } else {
2728	      lines.push(raw);
2729	    }
2730	  }
2731	  return lines;
2732	}
