2734	// 拆分内容行为 属性名;参数:值；属性名忽略大小写（统一转大写返回）
2735	function parseContentLine(
2736	  line: string,
2737	  bad: (reason: string) => never,
2738	): {name: string; params: string[]; value: string} {
2739	  const colon = line.indexOf(':');
2740	  if (colon < 0) bad(`内容行缺少 “:”: “${line}”`);
2741	  const head = line.slice(0, colon);
2742	  const value = line.slice(colon + 1);
2743	  const segs = head.split(';');
2744	  if (!/^[A-Za-z0-9-]+$/.test(segs[0])) bad(`属性名非法: “${segs[0]}”`);
2745	  return {name: segs[0].toUpperCase(), params: segs.slice(1), value};
2746	}
