2798	// 仍一律拒绝的重复相关属性（RRULE 与 EXDATE 已支持按周重复的受限子集）
2799	const ICAL_RECURRENCE_PROPS = new Set(['RDATE', 'EXRULE', 'RECURRENCE-ID']);
