2835	// 解析一条 EXDATE 属性：参数沿用浮动时间限制（与 DTSTART/DTEND 相同）；
2836	// 值可为一个或多个以逗号分隔的浮动时间（逗号在未转义状态下分隔），各时间
2837	// 必须真实有效，秒为 00；只能匹配原开始时间（由调用方与展开结果比对）。
2838	// 同一事件允许多行 EXDATE，所有时间合并后按集合去重。
2839	function parseExdateValue(
2840	  params: string[],
2841	  value: string,
2842	  bad: (reason: string) => never,
2843	): Array<{raw: string; min: number}> {
2844	  assertFloatingDateTimeParams(params, 'EXDATE ', bad);
2845	  const parts = value.split(',');
2846	  if (parts.some((p) => p.trim() === '')) bad('EXDATE 存在空的时间值（逗号列表每项都须是浮动时间）');
2847	  return parts.map((p) => parseIcalDateTime(p.trim(), 'EXDATE ', bad));
2848	}
