21	// 从而在不调整任何权限的前提下，可重复地触发真实保存失败。
22	const LONG_NAME = 'f'.repeat(250) + '.json';
23	
24	// ---------------------------------------------------------------------------
25	// 基础设施
26	// ---------------------------------------------------------------------------
27	
28	interface CliResult {
29	  status: number;
30	  stdout: string;
31	  stderr: string;
32	}
