40	function ok(df: string, args: string[], ctx: string): CliResult {
41	  const r = runCli(df, args);
42	  assert.equal(
43	    r.status,
44	    0,
45	    `[${ctx}] 期望退出 0，实际 ${r.status}\n命令: ${args.join(' ')}\nstderr:\n${r.stderr}\nstdout:\n${r.stdout}`,
