let heldLockPath: string | null = null;

async function acquireWriteLock(file: string): Promise<void> {
  if (heldLockPath !== null) return;
  const lockPath = lockPathFor(file);
  const content = JSON.stringify({...}) + '\n';
  const deadline = Date.now() + LOCK_TIMEOUT_MS;
  for (;;) {
    try {
      await writeFile(lockPath, content, {encoding: 'utf8', flag: 'wx'});
      heldLockPath = lockPath;
      return;
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') {
        throw new BizError(`无法取得数据文件写入保护（锁文件 ${lockPath}）：${(err as Error).message}`);
      }
      if (Date.now() >= deadline) {
        // 读取占用者信息用于说明
        let owner = '';
        try {
          const raw = JSON.parse(await readFile(lockPath, 'utf8'));
          owner = `（占用进程 PID ${raw.pid}，始于 ${raw.acquiredAt}）`;
        } catch { /* 忽略 */ }
        throw new BizError(
          `数据文件 ${file} 正被其他进程占用${owner}：${LOCK_TIMEOUT_MS / 1000} 秒内未能取得写入保护，本次未做任何改动；` +
          '可稍后重试。若确认原写入进程已异常退出，请使用 recover-lock 解除残留保护。',
        );
      }
      await new Promise((r) => setTimeout(r, LOCK_RETRY_MS + Math.floor(Math.random() * 20)));
    }
  }
}

async function releaseWriteLock(): Promise<void> {
  const lockPath = heldLockPath;
  if (lockPath === null) return;
  heldLockPath = null;
  try {
    // 仅删除本进程取得的保护：内容不符（例如已被恢复并被他人重新取得）时不删
    const raw = await readFile(lockPath, 'utf8');
    const info = JSON.parse(raw);
    if (info.pid !== process.pid || info.host !== hostname()) return;
    await unlink(lockPath);
  } catch {
    // 锁文件已不存在或无法处理：不影响本次结果
  }
}
