```ts
async function cmdRecoverLock(args: string[]): Promise<void> {
  const {values, positionals} = parseFlags(args, []);
  if (values.size > 0) throw new UsageError(...);
  if (positionals.length > 0) throw new UsageError('用法: recover-lock（解除本数据文件的残留写入保护）');

  const file = activeDataFile;
  const lockPath = lockPathFor(file);

  const readLock = async () => {
    const stat = await lstat(lockPath);
    const text = await readFile(lockPath, 'utf8');
    return {stat, text};
  };

  let first;
  try {
    first = await readLock();
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
      console.log(`数据文件 ${file} 当前没有写入保护残留，无需恢复。`);
      return;
    }
    throw new BizError(`无法读取写入保护文件 ${lockPath}: ${(err as Error).message}`);
  }

  let info: LockInfo;
  try {
    info = JSON.parse(first.text);
    if (typeof info.pid !== 'number' || !Number.isInteger(info.pid) || info.pid <= 0) throw new Error('bad');
  } catch {
    throw new BizError(`写入保护文件 ${lockPath} 内容无法辨认，无法确认原写入进程，拒绝解除（请人工检查后删除该文件）`);
  }

  const pidStatus = checkPid(info.pid);
  if (pidStatus === 'alive') {
    throw new BizError(`数据文件 ${file} 的写入保护由进程 ${info.pid} 持有，该进程仍在运行，拒绝解除（保护存在时长不作为解除依据）`);
  }
  if (pidStatus === 'unknown') {
    throw new BizError(`无法确认原写入进程 ${info.pid} 是否已退出（无权限查询），拒绝解除写入保护`);
  }
  // dead: 再次核对文件未被替换后删除
  let second;
  try {
    second = await readLock();
  } catch (err) {
    if (ENOENT) { console.log('写入保护已被解除（可能由另一恢复入口处理），无需重复操作。'); return; }
    throw ...;
  }
  if (second.stat.dev !== first.stat.dev || second.stat.ino !== first.stat.ino || second.text !== first.text) {
    throw new BizError('写入保护在核对期间已变化（可能已有新的写入者），拒绝解除');
  }
  await unlink(lockPath);
  console.log(`已解除数据文件 ${file} 的残留写入保护（原写入进程 ${info.pid} 已退出）。数据文件与标识计数未做任何改动，也不重放任何命令。`);
}
